import java.util.ArrayList;

public class Lote {
    // Definicion de Atributos. Lo dejé como private para implementar tipos de lotes (puede ser util? Quizás?)

    private String codigoLote;
    private Nodo nodo;
    private ArrayList<Trabajo> trabajos; //Listado de trabajo
    private String estadoLote;

    // Constructor default
    public Lote() {
        codigoLote = "";
        nodo = null;
        trabajos = new ArrayList<Trabajo>();
        estadoLote = "Preparacion";
    }

	//Nuevos atributos
    public Lote(String codigo, Nodo nodo) {
        codigoLote = codigo;
        this.nodo = nodo;
        trabajos = new ArrayList<Trabajo>();
        estadoLote = "Preparacion";
    }

    // Getter (no es necesario un setter, las reglas ya funcionan como están.) No necesito datos del usuario ni nada, yo manejaré todo.

    public String getCodigoLote() {
        return codigoLote;
    }

    public Nodo getNodo() {
        return nodo;
    }

    public String getEstadoLote() {
        return estadoLote;
    }


    // Cálculo de horas asignadas

    public float horasAsignadas() {
        float total = 0;
        // Suma las horas estimadas de cada trabajo. (para cada trabajo de la clase Trabajo en el listado trabajos)
        for (Trabajo trabajo : trabajos) {
			//Suma sus horas
            total += trabajo.getHorasEstimadas();
        }
		//Regresar el total
        return total;
    }


    // Horas disponibles
    public float capacidadDisponible() {
		//Capacidad - horasAsignadas
        return nodo.getCapacidad() - horasAsignadas();
    }


    // Asignar un nuevo trabajo. Voy a verificar todo:
    public boolean asignarTrabajo(Trabajo trabajo) {
        // Si el estado no es preparación... falso, no asignaré trabajo
        if (!estadoLote.equals("Preparacion")) {
            return false;
        }
        // Debe estar en cola
        if (!trabajo.getEstado().equals("En cola")) {
            return false;
        }
        // Solo si no extiende el máximo
        if (trabajo.getHorasEstimadas() > capacidadDisponible()) {
            return false;
        }
        // Solo si es compatible
        if (!trabajo.compatNodo(nodo)) {
            return false;
        }
		//SI Y SOLO SI (doble implicacion) se cumplió toooodo lo demás, entonces asignalo y cambia el estado del trabajo.
        trabajos.add(trabajo);
        trabajo.setEstado("Asignado");

        return true;
    }


    // Retirar el trabajo

    public boolean retirarTrabajo(Trabajo trabajo) {

        // Si ya se inició, casaca, no lo sacas
        if (!estadoLote.equals("Preparacion")) {
            return false;
        }

        // Si pertenece al lote
        if (!trabajos.contains(trabajo)) {
            return false;
        }

        // Quitarlo y eliminar el trabajo, y volverlo a poner en estado
        trabajos.remove(trabajo);
        trabajo.setEstado("En cola");

        return true;
    }


    // Iniciar el lote

    public int iniciarLote() {

        // El lote está en preparación?
        if (!estadoLote.equals("Preparacion")) {
            return -1;
        }

        // El lote está vacío?
        if (trabajos.isEmpty()) {
            return -1;
        }

        int reintentos = 0;
        // Cuenta los reintentos antes de incrementar los contadores de reintentos (Y CON ESO, saber cuantos Q25 aumentar al conteo completo)
        for (Trabajo trabajo : trabajos) {
            if (trabajo.getContador() > 0) {
                reintentos++;
            }
            // Cambiar el estado del trabajo
            trabajo.iniciarEjecucion();
        }

        // Cambia el estado del lote
        estadoLote = "En ejecucion";
        return reintentos;
    }


    // Registrar reintentos

    public boolean registrarResultado(Trabajo trabajo, boolean completado) {
        // Verifica si está el lote en ejecución
        if (!estadoLote.equals("En ejecucion")) {
            return false;
        }

        // El trabajo debe pertenecer al lote (dah)
        if (!trabajos.contains(trabajo)) {
            return false;
        }

        // Solo asignar un estado a los que están en ejecución
        if (!trabajo.getEstado().equals("En ejecución")) {
            return false;
        }

        if (completado) {
			//Ahora sí, verificadr si está completo
            trabajo.setEstado("Completado");
        } 
		
		else {
            // Comprueba si puede hacerse (ha hecho menos intentos de los que se pueden)
            if (trabajo.getContador() < trabajo.maxIntentos()) {
                trabajo.setEstado("En cola");
				//Si no, no se puede
            } else {
                trabajo.setEstado("Cancelado");
            }
        }

        // SCuando se tengan todos los resultados, cerrar el Lote
        if (verificarResultado()) {
            estadoLote = "Cerrado";
			//Liberar el NODO
            nodo.setDisponibilidad(true);
        }

        return true;
    }

    // Verificar Resultados (Mostrarlo pues)
    public boolean verificarResultado() {
		//Para cada trabajo en trabajo, revisa si alguno está en ejecución.
        for (Trabajo trabajo : trabajos) {
            if (trabajo.getEstado().equals("En ejecución")) {
                return false;
            }
        }
        return true;
    }


    // El toString de papa Object, necesito este

    @Override
    public String toString() {

        return "Código del lote: " + codigoLote
            + "\nNodo: " + nodo.getCodigoNodo()
            + "\nEstado: " + estadoLote
            + "\nHoras asignadas: " + horasAsignadas()
            + "\nCapacidad disponible: "
            + capacidadDisponible();
    }
}
